from rdkit import Chem
from rdkit.Chem import AllChem, rdMolTransforms
import numpy as np, math
class Builder:
 def __init__(self): self.rw=Chem.RWMol(); self.idx={}
 def atom(self,sym,name=None, aromatic=False, noimp=False):
  a=Chem.Atom(sym)
  if aromatic:a.SetIsAromatic(True)
  if noimp:a.SetNoImplicit(True)
  i=self.rw.AddAtom(a)
  if name:self.idx[name]=i
  return i
 def bond(self,a,b,t=Chem.BondType.SINGLE):self.rw.AddBond(a,b,t)
 def ipr(self,a,n):
  c=self.atom('C',n+'_ch');self.bond(a,c)
  for j in range(2):self.bond(c,self.atom('C',n+'_m'+str(j)))
 def dipp(self,N,name):
  ar=[self.atom('C',name+'_ar'+str(i),True) for i in range(6)]
  for i in range(6):self.bond(ar[i],ar[(i+1)%6],Chem.BondType.AROMATIC)
  self.bond(N,ar[0]);self.ipr(ar[1],name+'_ipra');self.ipr(ar[5],name+'_iprb')
 def core(self,name):
  c=self.atom('C',name+'_carb',noimp=True);n1=self.atom('N',name+'_n1');a=self.atom('C',name+'_ch1');b=self.atom('C',name+'_ch2');n2=self.atom('N',name+'_n2')
  self.bond(c,n1);self.bond(n1,a);self.bond(a,b,Chem.BondType.DOUBLE);self.bond(b,n2);self.bond(n2,c)
  return c,n1,a,b,n2
 def build(self,mode):
  c,n1,a,b,n2=self.core(mode)
  if mode=='top':
   ar=[self.atom('C',f'tar{i}',True) for i in range(6)]
   for i in range(6):self.bond(ar[i],ar[(i+1)%6],Chem.BondType.AROMATIC)
   self.bond(n1,ar[0]);self.ipr(ar[1],'tipr')
   sub=self.atom('C','alkC',noimp=True);self.bond(ar[5],sub)
   ch2=self.atom('C','alkCH2');self.bond(sub,ch2,Chem.BondType.DOUBLE)
   me=self.atom('C','alkMe');self.bond(sub,me)
   self.dipp(n2,'tdipp')
  else:
   self.dipp(n1,'dippA');self.dipp(n2,'dippB')
  m=self.rw.GetMol();Chem.SanitizeMol(m);m=Chem.AddHs(m)
  return m,self.idx

def rot_to(a,b):
 a=a/np.linalg.norm(a);b=b/np.linalg.norm(b);v=np.cross(a,b);s=np.linalg.norm(v);c=np.dot(a,b)
 if s<1e-9:return np.eye(3) if c>0 else np.diag([-1.,-1.,1.])
 K=np.array([[0,-v[2],v[1]],[v[2],0,-v[0]],[-v[1],v[0],0]])
 return np.eye(3)+K+K@K*((1-c)/(s*s))
def orient(m,idx,mode,z):
 conf=m.GetConformer();p=np.array(conf.GetPositions()); c=idx[mode+'_carb'];n1=idx[mode+'_n1'];n2=idx[mode+'_n2']
 R=rot_to((p[n1]+p[n2])/2-p[c],np.array([0.,0.,1 if z>0 else -1.]))
 p=(p-p[c])@R.T
 v=p[n2]-p[n1]; ang=math.atan2(v[1],v[0]);t=-ang
 Rz=np.array([[math.cos(t),-math.sin(t),0],[math.sin(t),math.cos(t),0],[0,0,1]])
 p=p@Rz.T+np.array([0.,0.,z])
 for i,x in enumerate(p):conf.SetAtomPosition(i,x.tolist())
 return p

def make(mode,z,seed):
 B=Builder();m,idx=B.build(mode);pr=AllChem.ETKDGv3();pr.randomSeed=seed;pr.useRandomCoords=False
 r=AllChem.EmbedMolecule(m,pr);print(mode,'embed',r,'atoms',m.GetNumAtoms(),'MMFF',AllChem.MMFFHasAllMoleculeParams(m))
 if r==0:AllChem.MMFFOptimizeMolecule(m,maxIters=500)
 p=orient(m,idx,mode,z);return m,idx,p
